mapper.select:
SELECT records.uuid, records.organization_uuid, records.workspace_uuid, records.document FROM ( SELECT m.uuid,
'platform' AS organization_uuid, 'platform' AS workspace_uuid, t.organization_uuid, t.workspace_uuid, m.organization_uuid, m.workspace_uuid,
AS document FROM m JOIN mcp_tunnels t ON t.uuid = m.tunnel_uuid ) records WHERE records.document IS NOT NULL AND records.uuid > #{after} ORDER BY records.uuid LIMIT #{limit}
